//! FrameSet integrity, checked against the C library for every Frame class.
//!
//! `integrity_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/integrity_probe.c`. Each case joins a Frame of one
//! class to a plain base Frame with a UnitMap, changes attributes of that
//! current Frame through the FrameSet, and transforms points from the base
//! Frame to the current one. C restores the integrity of a FrameSet with one
//! routine for every class (frameset.c `RestoreIntegrity`): it converts the
//! recorded state of the current Frame to its new state with `astConvert`,
//! and reports `AST__ILOST` when no conversion exists.

use crate::common::native_dump;
// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "integrity_oracle/cases.rs"]
mod cases;

use starlink_ast::coords::PointSet;
use starlink_ast::error::{AstResult, ErrorCode};
use starlink_ast::frames::{
    BasicFrameBuilder, CmpFrame, DSBSpecFrame, FluxFrame, FluxSystem, Frame, FrameRef, FrameSet,
    SideBand, SkyFrame, SkyRefIs, SkySystem, SpecFluxFrame, SpecFrame, SpecSystem, StdOfRest,
    TimeFrame, TimeScale, TimeSystem,
};
use starlink_ast::mappings::UnitMap;

/// J2050 and J2010 as Modified Julian Dates.
const J2050: f64 = 69807.0;
const J2010: f64 = 55197.0;

/// RefRA and RefDec of the SpecFrame cases (integrity_probe.c `REF_RA`).
const REF_RA: f64 = 1.0471975511965976;
const REF_DEC: f64 = 0.523_598_775_598_298_8;

fn sky(system: SkySystem) -> SkyFrame {
    let mut f = SkyFrame::unset_system();
    f.set_system(system);
    f
}

fn spec_ghz(system: SpecSystem) -> SpecFrame {
    let mut f = SpecFrame::new(system);
    f.set_unit(1, "GHz").unwrap();
    f
}

/// A FrameSet whose base is a plain Frame joined to `current` by a UnitMap.
fn frameset(current: Box<dyn Frame>) -> FrameSet {
    let naxes = current.naxes();
    let base = BasicFrameBuilder::new(naxes).build().unwrap();
    let mut fs = FrameSet::new(Box::new(base));
    fs.add_frame(FrameRef::Base, Box::new(UnitMap::new(naxes)), current)
        .unwrap();
    fs
}

/// Change the current Frame, as a `T`, through the FrameSet.
fn through<T: 'static>(fs: &mut FrameSet, f: impl FnOnce(&mut T)) -> AstResult<()> {
    fs.with_integrity(|cur| {
        f(cur
            .as_any_mut()
            .downcast_mut::<T>()
            .expect("current Frame class"));
        Ok(())
    })
}

/// Change the SkyFrame component of a CmpFrame current Frame.
fn through_cmp_sky(fs: &mut FrameSet, f: impl FnOnce(&mut SkyFrame)) -> AstResult<()> {
    through(fs, |cmp: &mut CmpFrame| {
        f(cmp
            .frame1_mut()
            .as_any_mut()
            .downcast_mut::<SkyFrame>()
            .unwrap())
    })
}

/// Build the case's FrameSet and apply its settings as the probe does.
fn run(name: &str) -> AstResult<FrameSet> {
    let mut fs;
    match name {
        "flux_unit_jy" | "flux_system_sfcbr" => {
            let mut flux = FluxFrame::new(FluxSystem::FluxDen);
            flux.set_spec_val(1.4e9);
            fs = frameset(Box::new(flux));
            if name == "flux_unit_jy" {
                fs.set_unit(1, "Jy")?;
            } else {
                through(&mut fs, |f: &mut FluxFrame| {
                    f.set_system(FluxSystem::SBright).unwrap()
                })?;
            }
        }
        "specflux_unit2_jy" | "specflux_unit1_mhz" => {
            let sf = SpecFluxFrame::new(
                spec_ghz(SpecSystem::Freq),
                FluxFrame::new(FluxSystem::FluxDen),
            );
            fs = frameset(Box::new(sf));
            if name == "specflux_unit2_jy" {
                fs.set_unit(2, "Jy")?;
            } else {
                fs.set_unit(1, "MHz")?;
            }
        }
        "frame_activeunit_km" => {
            let mut f = BasicFrameBuilder::new(1).unit(1, "m").build().unwrap();
            f.set_active_unit(true);
            fs = frameset(Box::new(f));
            fs.set_unit(1, "km")?;
        }
        "frame_title" => {
            fs = frameset(Box::new(BasicFrameBuilder::new(2).build().unwrap()));
            fs.set_title("Renamed")?;
        }
        "sky_fk5_equinox" => {
            fs = frameset(Box::new(sky(SkySystem::Fk5)));
            through(&mut fs, |f: &mut SkyFrame| f.set_equinox_mjd(J2050))?;
        }
        "sky_gappt_epoch" => {
            fs = frameset(Box::new(sky(SkySystem::Gappt)));
            fs.set_epoch_mjd(J2010)?;
        }
        "sky_fk4_to_fk5" => {
            fs = frameset(Box::new(sky(SkySystem::Fk4)));
            through(&mut fs, |f: &mut SkyFrame| f.set_system(SkySystem::Fk5))?;
        }
        "sky_icrs_to_galactic" => {
            fs = frameset(Box::new(sky(SkySystem::Icrs)));
            through(&mut fs, |f: &mut SkyFrame| {
                f.set_system(SkySystem::Galactic)
            })?;
        }
        "sky_skyref_origin" => {
            fs = frameset(Box::new(sky(SkySystem::Icrs)));
            through(&mut fs, |f: &mut SkyFrame| {
                f.set_sky_ref(1, cases::SKYREF[0]).unwrap();
                f.set_sky_ref(2, cases::SKYREF[1]).unwrap();
            })?;
            through(&mut fs, |f: &mut SkyFrame| {
                f.set_sky_ref_is(SkyRefIs::Origin)
            })?;
        }
        "sky_alignoffset_galactic" => {
            let mut f = sky(SkySystem::Icrs);
            f.set_align_offset(true);
            f.set_sky_ref_is(SkyRefIs::Origin);
            f.set_sky_ref(1, cases::SKYREF[0]).unwrap();
            f.set_sky_ref(2, cases::SKYREF[1]).unwrap();
            fs = frameset(Box::new(f));
            through(&mut fs, |f: &mut SkyFrame| {
                f.set_system(SkySystem::Galactic)
            })?;
        }
        "sky_unknown_title" => {
            fs = frameset(Box::new(sky(SkySystem::Unknown)));
            fs.set_title("Renamed")?;
        }
        "sky_permuted_galactic" => {
            let mut f = sky(SkySystem::Icrs);
            f.perm_axes(&[2, 1]).unwrap();
            fs = frameset(Box::new(f));
            through(&mut fs, |f: &mut SkyFrame| {
                f.set_system(SkySystem::Galactic)
            })?;
        }
        "cmp_sky_spec_equinox" | "cmp_sky_spec_galactic" => {
            let cmp = CmpFrame::new(
                Box::new(sky(SkySystem::Fk5)),
                Box::new(spec_ghz(SpecSystem::Freq)),
            );
            fs = frameset(Box::new(cmp));
            if name == "cmp_sky_spec_equinox" {
                through_cmp_sky(&mut fs, |f| f.set_equinox_mjd(J2050))?;
            } else {
                through_cmp_sky(&mut fs, |f| f.set_system(SkySystem::Galactic))?;
            }
        }
        "spec_vrad" => {
            let mut f = spec_ghz(SpecSystem::Freq);
            f.set_rest_freq(230.538e9);
            fs = frameset(Box::new(f));
            through(&mut fs, |f: &mut SpecFrame| {
                f.set_system(SpecSystem::Vradio).unwrap()
            })?;
        }
        "spec_lsrk" => {
            let mut f = spec_ghz(SpecSystem::Freq);
            f.set_epoch_mjd(J2010);
            f.set_ref_ra(REF_RA);
            f.set_ref_dec(REF_DEC);
            fs = frameset(Box::new(f));
            through(&mut fs, |f: &mut SpecFrame| {
                f.set_std_of_rest(StdOfRest::Lsrk).unwrap()
            })?;
        }
        "spec_sourcevel" => {
            let mut f = spec_ghz(SpecSystem::Freq);
            f.set_std_of_rest(StdOfRest::Source).unwrap();
            f.set_ref_ra(REF_RA);
            f.set_ref_dec(REF_DEC);
            fs = frameset(Box::new(f));
            through(&mut fs, |f: &mut SpecFrame| f.set_source_vel_cur(100.0))?;
        }
        "time_jd" | "time_utc" | "time_origin" => {
            let mut f = TimeFrame::new(TimeSystem::Mjd);
            f.set_timescale(TimeScale::Tai).unwrap();
            fs = frameset(Box::new(f));
            match name {
                "time_jd" => through(&mut fs, |f: &mut TimeFrame| {
                    f.set_system(TimeSystem::Jd).unwrap()
                })?,
                "time_utc" => through(&mut fs, |f: &mut TimeFrame| {
                    f.set_timescale(TimeScale::Utc).unwrap()
                })?,
                _ => through(&mut fs, |f: &mut TimeFrame| f.set_time_origin(55000.0))?,
            }
        }
        "dsb_usb" => {
            let mut f = DSBSpecFrame::new(SpecSystem::Freq);
            f.set_unit(1, "GHz").unwrap();
            f.set_dsb_centre_cur(230.0).unwrap();
            f.set_if_ghz(4.0);
            f.set_sideband(SideBand::LSB);
            fs = frameset(Box::new(f));
            through(&mut fs, |f: &mut DSBSpecFrame| {
                f.set_sideband(SideBand::USB)
            })?;
        }
        other => panic!("no Rust set-up for case {other}"),
    }
    Ok(fs)
}

/// The input points of each case, one coordinate per axis, as the probe
/// passes them.
fn points(name: &str) -> Vec<Vec<f64>> {
    let p: &[&[f64]] = match name {
        n if n.starts_with("flux_") => &[&[1.0e-26], &[3.0e-26]],
        n if n.starts_with("specflux_") => &[&[1.0, 1.0e-26], &[2.0, 3.0e-26]],
        "frame_activeunit_km" => &[&[1000.0], &[5.0]],
        n if n.starts_with("cmp_") => &[&[1.0, 0.5, 1.0], &[4.2, -0.9, 2.0]],
        n if n.starts_with("spec_") || n.starts_with("dsb_") => &[&[230.0], &[345.0]],
        n if n.starts_with("time_") => &[&[0.25], &[1.75]],
        _ => &[&[1.0, 0.5], &[4.2, -0.9]],
    };
    p.iter().map(|q| q.to_vec()).collect()
}

/// Whether a case's outcome matches C exactly, with a description of the
/// difference when it does not.
fn compare(name: &str, expected: Result<&[&[f64]], &str>) -> Result<(), String> {
    match (run(name), expected) {
        (Err(e), Err("ILOST")) if e.code() == ErrorCode::Ilost => Ok(()),
        (Err(e), want) => Err(format!("{name}: error {e}, C gives {want:?}")),
        (Ok(_), Err(want)) => Err(format!("{name}: no error, C reports {want}")),
        (Ok(fs), Ok(want)) => {
            let input = points(name);
            let naxes = input[0].len();
            let cols: Vec<Vec<f64>> = (0..naxes)
                .map(|a| input.iter().map(|p| p[a]).collect())
                .collect();
            let col_refs: Vec<&[f64]> = cols.iter().map(Vec::as_slice).collect();
            let pts = PointSet::from_columns(&col_refs).unwrap();
            let map = fs.mapping(FrameRef::Base, FrameRef::Current).unwrap();
            let out = map.transform(&pts, true).unwrap();
            let got: Vec<Vec<f64>> = (0..input.len()).map(|i| out.point(i).to_vec()).collect();
            let want: Vec<Vec<f64>> = want.iter().map(|p| p.to_vec()).collect();
            if got.len() == want.len() && crate::common::c_values_eq(&got.concat(), &want.concat())
            {
                Ok(())
            } else {
                Err(format!("{name}: got {got:?}, C gives {want:?}"))
            }
        }
    }
}

#[test]
fn integrity_matches_the_c_library() {
    let failures: Vec<String> = cases::CASES
        .iter()
        .filter_map(|&(name, expected)| compare(name, expected).err())
        .collect();
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from C:\n{}",
        failures.len(),
        cases::CASES.len(),
        failures.join("\n")
    );
}

/// A change to the current Frame that leaves the conversion from its old
/// state a UnitMap does not remap the Frame, as `RestoreIntegrity` does not,
/// so the FrameSet's Mappings are left as they are rather than re-simplified.
/// `sparse.ast` holds a Mapping that simplifies further than it stands.
#[test]
fn unit_change_leaves_mappings_alone() {
    let text = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/programs/testfitschan/sparse.ast"
    ))
    .unwrap();
    let starlink_ast::AnyObject::FrameSet(mut fs) =
        starlink_ast::from_native_string(&text).unwrap()
    else {
        panic!("sparse.ast is not a FrameSet");
    };
    let before = native_dump(&starlink_ast::AnyObject::FrameSet(fs.clone())).unwrap();
    fs.with_integrity(|_| Ok(())).unwrap();
    let after = native_dump(&starlink_ast::AnyObject::FrameSet(fs)).unwrap();
    assert_eq!(before, after);
}
